    'admin_leader_operating_system.forever.comparison_note' => 'Az aktivitás, a könnyű lépések és a kihívást jelentő lépések számlálása FCC-fiókonként történik, és a kiválasztott időszakot közvetlenül megelőző, azonos hosszúságú időszakkal hasonlítja össze. A feliratkozott, elkezdett és befejezett értékeknél a nagy szám az összesített, végleges érték, a változás pedig a két azonos hosszúságú időszak új eseményeit hasonlítja össze. A havi személyes CC és mindkét 4 CC-mutató a Forever ID alapján kiszűri a duplikációkat, és csak az aktuális FLP-struktúrát veszi figyelembe. A hivatalos 4 CC-szám a megerősített FLP360-jelzéseket számolja; a tényleges 4 CC az előírt 1/0 értéket használja, és csak akkor alkalmazza a tartalék képletet, ha ez a jelzés hiányzik: személyes CC ≥ 1 és összesített aktív CC ≥ 4, a határérték is beleszámít.',
