    'admin_leader_operating_system.leader.opportunity_modal_intro' => 'A növekedési mozgástér jelenleg %s. Az alábbiakban azokat a változtatásokat és teendőket találod, amelyek a legnagyobb valószínűséggel segítenek ennek az együttműködőnek gyorsabban előrelépni és jobb eredményt elérni.',
    'admin_leader_operating_system.leader.opportunity_modal_empty' => 'Jelenleg nincsenek további jelzések, de továbbra is az erősebb cselekvésre ösztönző felhívásokra, a jobb konverzióra és az egyszerűbb regisztrációs vagy vásárlási folyamatra érdemes összpontosítani.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.label' => 'Növeld a webáruházra vagy kedvezményes céloldalakra mutató kattintások arányát',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.text' => 'Az együttműködőnek összesen %s kattintása van, de ezeknek csak a %s%%-a vezet a Forever webshopra vagy kedvezményes céloldalra.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_1' => 'Tedd az oldalon feljebb a webáruházra vagy a kedvezményre mutató CTA-t, és ismételd meg a profil vagy a blogbejegyzés alsó részénél.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_2' => 'Helyezz el egyértelműbb cselekvésre ösztönző felhívást a fő forgalmi útvonalon, hogy a látogatók egy Forever-céloldalra jussanak, ne csupán tájékoztató tartalomhoz.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_2_source' => 'A %s forrásnál próbálj ki egy egyértelműbb CTA-t, amely közvetlenül a tartalomból a Forever webshopba vagy a kedvezményes ajánlathoz vezeti a felhasználókat.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_3' => 'Ellenőrizd, hogy a blog-, értékesítési és kedvezményblokkok kellően láthatóvá teszik-e a vásárlás útját, és elégszer jelennek-e meg.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.label' => 'Alakítsd a webshopra érkező kattintásokat regisztrációvá vagy vásárlássá',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.text' => 'Az együttműködőnek már %s webshopkattintása van, de ebben az időszakban még egyetlen regisztrációja sincs.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_1' => 'Ellenőrizd, hogy a kattintás a megfelelő ajánlói URL-t nyitja-e meg, és hiba nélkül a kívánt oldalra vagy webáruház-oldalra vezet-e.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_2' => 'Javítsd az üzenetet még a kattintás előtt: mondd el, mit kap a látogató, miért érdemes most kattintania, és mi történik, miután belép a Forever oldalára.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_3' => 'Tesztelj egyszerűbb regisztrációs vagy vásárlási folyamatot, és távolítsd el az első kattintás utáni zavaró lépéseket.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_3_country' => 'Ha a forgalom nagy része innen érkezik: %s, ellenőrizd, hogy a céloldal megfelelően lokalizált-e, és a megfelelő piaci verzió nyílik-e meg.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.label' => 'Növeld a konverziós arányt a forgalom növekedése mellett',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.text' => 'A forgalom %s%%-kal nő, de a regisztrációs arány csak %s%%, ezért a többletkattintások még nem hoznak elegendő eredményt.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_1' => 'Tartsd meg a növekedést hozó forrást, de finomítsd a CTA szövegét és a bevezető üzenetet, hogy jobban felmérjék a vásárlási szándékot.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_2' => 'A cselekvésre ösztönző gomb elé illessz be egy bizalmat építő elemet, például egy véleményt, eredményt, rövid GYIK-et vagy egyértelmű magyarázatot arról, mi történik a kattintás után.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_3' => 'Hasonlítsd össze a kattintások forrásait, és továbbra is csak azokat a csatornákat részesítsd előnyben, amelyek regisztrációkat vagy jobb minőségű érdeklődőket hoznak, nem csupán nagy forgalmat.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.label' => 'Használd fel a meglévő érdeklődést egy hatékonyabb értékesítési út kialakításához',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.text' => 'Az alkalmazás már generál érdeklődést WhatsAppon (%1$s), termékek iránt (%2$s) és regisztrációk formájában (%3$s), de ez még mindig nem irányít elég embert a webáruházba.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.step_1' => 'Helyezz el egy jól látható fő belépési pontot az áruházhoz, a többi értékesítési lehetőség fölé.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.step_2' => 'Igazítsd egymáshoz a tartalomban, a WhatsAppban és az értékesítési blokkokban szereplő üzeneteket, hogy mind ugyanarra a következő lépésre mutassanak.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.step_3' => 'Tartsd meg az érdeklődést gyűjtő blokkokat, de egyértelműen különítsd el azt a részt, ahol azonnal a vásárlásra vagy a feliratkozásra kell kattintani.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.label' => 'Tartsd fenn a lendületet kisebb optimalizálásokkal',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.text' => 'A fejlődési lehetőség nem egyetlen nagy problémából adódik, hanem több kisebb fejlesztési lehetőségből.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.step_1' => 'Továbbra is irányítsd a forgalmat a legeredményesebb, jól működő CTA-pontokra.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.step_2' => 'Továbbra is teszteld a főcím megfogalmazását, a CTA-k sorrendjét és a bizalmat erősítő elemeket, hogy megtartsd vagy csökkentsd a lehetőség pontszámát.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.step_3' => 'Továbbra is figyeld, hogy a többletkattintások regisztrációkat is eredményeznek-e, nem csak nagyobb forgalmat.',
